/// Test that zune-jpeg can decode progressive XYB (reference decoder).
#[test]
fn zune_jpeg_decodes_progressive_xyb() {
    let mut decoder = zune_jpeg::JpegDecoder::new(zune_jpeg::zune_core::bytestream::ZCursor::new(
        PROGRESSIVE_XYB_JPEG,
    ));
    let result = decoder.decode();

    assert!(result.is_ok(), "zune-jpeg should decode progressive XYB");
    let pixels = result.unwrap();
    assert_eq!(pixels.len(), 8 * 8 * 3, "8x8 RGB image = 192 bytes");
}

/// Test that jpegli-rs can decode progressive XYB JPEGs.
///
/// XYB progressive JPEGs use non-standard component IDs ('R'=82, 'G'=71, 'B'=66).
/// The decoder must properly handle UnexpectedEof during progressive DC scans
/// to avoid failing when scan data ends before all blocks are decoded.
#[test]
fn jpegli_decodes_progressive_xyb() {
    let result = jpegli::Decoder::new().decode(PROGRESSIVE_XYB_JPEG);

    assert!(
        result.is_ok(),
        "jpegli-rs should decode progressive XYB: {:?}",
        result.err()
    );
    let image = result.unwrap();
    assert_eq!(image.width, 8);
    assert_eq!(image.height, 8);
    assert_eq!(image.data.len(), 8 * 8 * 3);
}

/// Test that jpegli-rs can decode baseline (non-progressive) XYB JPEGs.
/// This works correctly - the bug is only in progressive decoding.
#[test]
fn jpegli_decodes_baseline_xyb() {
    // Create a baseline XYB JPEG using jpegli encoder
    let width = 8u32;
    let height = 8u32;
    let pixels: Vec<u8> = (0..width * height * 3).map(|i| (i % 256) as u8).collect();

    let jpeg_data = jpegli::Encoder::new()
        .width(width)
        .height(height)
        .use_xyb(true)
        .encode(&pixels)
        .expect("encode");

    // Verify it's baseline (not progressive)
    assert!(
        !is_progressive(&jpeg_data),
        "jpegli XYB should be baseline by default"
    );

    // Decode with jpegli-rs
    let result = jpegli::Decoder::new().decode(&jpeg_data);
    assert!(
        result.is_ok(),
        "jpegli-rs should decode baseline XYB: {:?}",
        result.err()
    );
}

/// Check if a JPEG is progressive by looking for SOF2 marker.
fn is_progressive(data: &[u8]) -> bool {
    let mut i = 0;
    while i < data.len() - 1 {
        if data[i] == 0xFF {
            let marker = data[i + 1];
            if marker == 0xC2 {
                // SOF2 = Progressive DCT
                return true;
            }
            if marker == 0xC0 {
                // SOF0 = Baseline DCT
                return false;
            }
        }
        i += 1;
    }
    false
}
